import sys
from collections import deque
data = list(map(int, sys.stdin.read().split()))
if data:
    n, r, w = data[0], data[1], data[2]
    timestamps = data[3:n+3]
    q = deque()
    for ts in timestamps:
        while q and q[0] <= ts - w:
            q.popleft()
        if len(q) < r:
            q.append(ts)
            print('ALLOWED')
        else:
            print('DENIED')
